import sys; sys.path.insert(0, str(WORK))
from cvlib import *
R = np.load(WORK/'base_reads.npz'); y=R['y']; res=np.load(WORK/'reserved.npy')
keep = np.setdiff1d(np.arange(768), res)
M = lambda L: R[f'mean_hidden_L{L}'][:,keep]
Y=np.eye(8)[y]
rng=np.random.RandomState(0)
def nys_cv(X, gamma, lams, ncent=768, seeds=(0,1), lin=False):
    out={l:[] for l in lams}
    for s in seeds:
        f=folds(y,5,s); S={l:np.zeros((len(y),8)) for l in lams}
        for i in range(5):
            tr=np.where(f!=i)[0]; te=np.where(f==i)[0]
            mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6
            Z=(X-mu)/sd; Z=Z/np.linalg.norm(Z,axis=1,keepdims=True)
            cidx=[]
            for c in range(8):
                ic=tr[y[tr]==c]; cidx+=list(rng.choice(ic, min(ncent//8,len(ic)), replace=False))
            C=Z[cidx]; F=np.exp(gamma*(Z@C.T-1))
            if lin: F=np.concatenate([F, Z],1)
            Ftr=F[tr]; fm=Ftr.mean(0); Ftr=Ftr-fm; Fte=F[te]-fm
            G=Ftr.T@Ftr; B=Ftr.T@(Y[tr]-Y[tr].mean(0))
            for l in lams: S[l][te]=Fte@np.linalg.solve(G+l*np.eye(G.shape[0]),B)
        for l in lams: out[l].append((S[l].argmax(1)==y).mean())
    return {l:round(float(np.mean(v)),4) for l,v in out.items()}
def kern_cv(X, kfun, lams, seeds=(0,1)):
    mu=X.mean(0); sd=X.std(0)+1e-6; Z=(X-mu)/sd; Z=Z/np.linalg.norm(Z,axis=1,keepdims=True)
    K=kfun(Z@Z.T); out={l:[] for l in lams}
    for s in seeds:
        f=folds(y,5,s); S={l:np.zeros((len(y),8)) for l in lams}
        for i in range(5):
            tr=f!=i; te=f==i
            for l in lams:
                A=np.linalg.solve(K[np.ix_(tr,tr)]+l*np.eye(tr.sum()), Y[tr]-Y[tr].mean(0)); S[l][te]=K[np.ix_(te,tr)]@A
        for l in lams: out[l].append((S[l].argmax(1)==y).mean())
    return {l:round(float(np.mean(v)),4) for l,v in out.items()}
X=M(1)
for g in [0.6,1,2,4]:
    print('exp-cos kernel', g, kern_cv(X, lambda C: np.exp(g*(C-1)), [1e-4,1e-3,1e-2]))
print('lin', kern_cv(X, lambda C: C, [1e-2,1e-1,1]))
print('quad', kern_cv(X, lambda C: C+0.5*C**2, [1e-3,1e-2,1e-1]))
print('quadonly', kern_cv(X, lambda C: C**2, [1e-3,1e-2,1e-1]))
for g in [0.6,1,2]:
    print('nys', g, nys_cv(X, g, [1e-5,1e-4,1e-3]))
